"""Apply the reviewed follow-up on the already-tested live-status branch."""
import base64,gzip,hashlib,subprocess
DATA=""
p=gzip.decompress(base64.b64decode(DATA))
assert hashlib.sha256(p).hexdigest()=='370fb0a8eed44071450b5908f7ffa62438469e1e9427402334c456febc3bf811'
subprocess.run(['git','apply','--check','-'],input=p,check=True)
subprocess.run(['git','apply','-'],input=p,check=True)
